package top.pxczxn.community.web.performance;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.core.annotation.Order; import org.springframework.stereotype.Component; import org.springframework.web.util.ContentCachingResponseWrapper; import java.io.IOException;
@Component @Order(20) public class PublicPerformanceFilter implements Filter { public void doFilter(ServletRequest request,ServletResponse response,FilterChain chain)throws IOException,ServletException {boolean publicGet=request instanceof HttpServletRequest r&&"GET".equals(r.getMethod())&&r.getRequestURI().startsWith("/api/v1/public/");if(!publicGet){chain.doFilter(request,response);return;}long start=System.nanoTime();ContentCachingResponseWrapper wrapped=new ContentCachingResponseWrapper((HttpServletResponse)response);try{chain.doFilter(request,wrapped);}finally{if(wrapped.getHeader("Cache-Control")==null)wrapped.setHeader("Cache-Control","public, max-age=60, stale-while-revalidate=120");wrapped.setHeader("Server-Timing","app;dur="+String.format(java.util.Locale.ROOT,"%.2f",(System.nanoTime()-start)/1_000_000d));wrapped.copyBodyToResponse();}} }
